///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fnSearch_ajaxsubmit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fnSearch_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearch_ajaxsubmit",
        method: "post",
        action: "/common/findDigitalIc.do",
        ref: "dma_fnSearchAjaxsubmitReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jlddst20024.tx_fnSearch_ajaxsubmit" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.fnSearchInit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearchInit = async function () {
    /* sdd-asis-lifecycle:begin fnSearchInit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("pageIndex", "1");
    await scwin.fnSearch();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.reflectCorpName
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.reflectCorpName = function () {
    /* sdd-asis-lifecycle:begin reflectCorpName — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let digitalIsuNm = $c.util.getComponent('ipt_digitalIsuNm').getValue();
    digitalIsuNm = encodeURI(digitalIsuNm);
    $c.util.getComponent('ipt_digitalIsuNm').getValue();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearch = async function () {
    /* sdd-asis-lifecycle:begin fnSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.setCodeName();
    scwin.reflectCorpName();
    $c.util.getComponent('ipt_beginIndex').setValue("");
    await scwin.tx_fnSearch_ajaxsubmit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCallBack
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.fnSearchCallBack = function (data) {
    /* sdd-asis-lifecycle:begin fnSearchCallBack — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    (($c.util.getComponent('contents')) && ($c.util.getComponent('contents')).removeAll ? ($c.util.getComponent('contents')).removeAll() : (($c.util.getComponent('contents')) && ($c.util.getComponent('contents')).setValue ? ($c.util.getComponent('contents')).setValue('') : void 0)).append(data);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setDigitalInfo
 * @author Inswave
 * @date 2026. 09. 29
 * @param isuSrtCd isuKorAbbrv isuCd
 * @returns
 * @hidden N
*/
scwin.setDigitalInfo = function (isuSrtCd, isuKorAbbrv, isuCd) {
    /* sdd-asis-lifecycle:begin setDigitalInfo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let str = "";
    str += "isuSrtCd : " + isuSrtCd + "\n";
    str += "isuKorAbbrv : " + isuKorAbbrv + "\n";
    str += "isuCd : " + isuCd + "\n";
    (((((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).scwin || {})) !== scwin && typeof (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).scwin || {})).setDigitalInfo === 'function' ? (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).scwin || {})).setDigitalInfo(isuSrtCd, isuKorAbbrv, isuCd) : void 0), $c.win.closePopup([isuSrtCd, isuKorAbbrv, isuCd]));
    this.close();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setCodeName
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.setCodeName = function () {
    /* sdd-asis-lifecycle:begin setCodeName — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('ipt_digitalIsuCd').setValue("");
    $c.util.getComponent('ipt_digitalIsuNm').setValue("");
    let digitalIsu = $c.util.getComponent('ipt_digitalIsu').getValue(); if (digitalIsu == null) { digitalIsu = ''; }
    digitalIsu = digitalIsu.toUpperCase();
    if (digitalIsu == null) {
        return;
    }
    if (digitalIsu === "") {
        return;
    }
    $c.util.getComponent('ipt_digitalIsuCd').setValue("");
    $c.util.getComponent('ipt_digitalIsuNm').setValue(digitalIsu);
    /* sdd-asis-lifecycle:end */
};
